-- Four sourced events (Prosecutor General / regional prosecutors); preserve scores and resolved cases.
DO $guard$ BEGIN
IF (SELECT count(*) FROM public.event_cases c WHERE c.case_key IN ('bank-bus','bank-curated-serious-03','bank-curated-serious-06','bank-curated-serious-23') AND c.status='ready' AND c.source_url IS NULL
AND NOT EXISTS(SELECT 1 FROM public.event_assignments a WHERE a.case_id=c.id)
AND NOT EXISTS(SELECT 1 FROM public.event_decisions d WHERE d.case_id=c.id)
AND NOT EXISTS(SELECT 1 FROM public.event_case_outcomes o WHERE o.case_id=c.id)
AND NOT EXISTS(SELECT 1 FROM public.event_collaboration_invites x WHERE x.case_id=c.id)
AND NOT EXISTS(SELECT 1 FROM public.event_discussion_messages x WHERE x.case_id=c.id)
AND NOT EXISTS(SELECT 1 FROM public.event_authority_evidence x WHERE x.case_id=c.id)
AND NOT EXISTS(SELECT 1 FROM public.budget_transfer_requests x WHERE x.event_case_id=c.id)
) <> 4 THEN RAISE EXCEPTION 'A target event has history or no longer matches the verified draft'; END IF;
END $guard$;
UPDATE public.event_cases AS c SET title='Омская область: восстановление регулярных автобусных маршрутов',situation='10 марта 2023 года Генеральная прокуратура Российской Федерации сообщила об улучшении транспортного обслуживания населения Омской области. Поводом для проверки стало в том числе обращение жительницы посёлка Омский, которой было трудно добираться до областного центра. После вмешательства прокуроров для посёлка с населением около 4,3 тысячи человек изменили расписание, добавили шесть рейсов и обеспечили работу автобусов большей вместимости.

При последующем изучении ситуации надзорные органы получили свыше 450 обращений граждан. Совместно с Ространснадзором и ГИБДД они проанализировали работу 35 транспортных предприятий. По опубликованным данным, меры позволили повысить транспортную доступность для 36 населённых пунктов с населением свыше 8,6 тысячи человек. Были организованы 11 новых муниципальных маршрутов, а в девяти посёлках увеличено число автобусных рейсов. В отношении перевозчиков, нарушавших расписание и требования безопасности, инициировали около 80 административных дел.

Дело показывает различие между формально установленным маршрутом и реальной возможностью жителя воспользоваться транспортом. Если автобусы не выходят на линию, не соответствуют потребностям по вместимости или не совпадают с расписанием, это затрагивает доступность медицинской помощи, образования и государственных услуг. Проверке подлежат фактическое движение транспорта, обращения пассажиров, параметры перевозок, условия контрактов и причины нарушений.

Статья 14 Федерального закона № 220-ФЗ определяет порядок организации регулярных перевозок по регулируемым тарифам. Уполномоченный орган не может ограничиться публикацией обещаний, но и не вправе произвольно распоряжаться бюджетом без проверки законных оснований. Как согласовать оперативные меры, обязанности перевозчиков, информирование граждан и измеримый контроль результата?',source_url='https://epp.genproc.gov.ru/ru/gprf/mass-media/news/archive/e476430/',
 source_note='Факт: официальное сообщение органов прокуратуры https://epp.genproc.gov.ru/ru/gprf/mass-media/news/archive/e476430/. Правовое основание: Федеральный закон от 13.07.2015 № 220-ФЗ, статья 14: организация регулярных перевозок по регулируемым тарифам.',
 decision_options='["Проверить выполнение рейсов, пассажиропоток и договорные обязанности перевозчиков; исправить расписание в законном порядке и проконтролировать его фактическое соблюдение.","Ограничиться общей информационной кампанией о развитии транспорта, а рассмотрение конкретных срывов рейсов перенести на следующий квартал.","Предложить жителям организовать поездки самостоятельно, не проверяя исполнение муниципальных маршрутов.","Увеличить финансирование всех перевозчиков без изучения графика рейсов, договорных условий и спроса.","Отменить действующие маршруты без анализа транспортной доступности и оценки последствий для жителей."]'::jsonb,
 effect_plan=jsonb_set(c.effect_plan,'{options}',(SELECT jsonb_agg(
 jsonb_set(jsonb_set(o.item,'{description}',to_jsonb(
  CASE WHEN o.item->>'key'='option_1' THEN 'Проверка фактического выполнения рейсов, вместимости и пассажиропотока позволяет определить меры организатора перевозок и договорные обязанности конкретных перевозчиков. Следует устранить подтверждённые нарушения, довести актуальное расписание до пассажиров и проверить результат. Объявление новых маршрутов без подтверждения их исполнения не восстанавливает доступность транспорта.'::text ELSE ('["Проверить выполнение рейсов, пассажиропоток и договорные обязанности перевозчиков; исправить расписание в законном порядке и проконтролировать его фактическое соблюдение.","Ограничиться общей информационной кампанией о развитии транспорта, а рассмотрение конкретных срывов рейсов перенести на следующий квартал.","Предложить жителям организовать поездки самостоятельно, не проверяя исполнение муниципальных маршрутов.","Увеличить финансирование всех перевозчиков без изучения графика рейсов, договорных условий и спроса.","Отменить действующие маршруты без анализа транспортной доступности и оценки последствий для жителей."]'::jsonb->>(o.pos::integer-1)) END
 )),'{legal_basis}',to_jsonb('Федеральный закон от 13.07.2015 № 220-ФЗ, статья 14: организация регулярных перевозок по регулируемым тарифам.'::text)) ORDER BY o.pos)
 FROM jsonb_array_elements(c.effect_plan->'options') WITH ORDINALITY AS o(item,pos)
 )) WHERE c.case_key='bank-bus' AND c.effect_plan->>'best_option_key'='option_1' AND jsonb_array_length(c.decision_options)=5;
UPDATE public.event_cases AS c SET title='Краснодар: доступность подъёмника возле больницы',situation='30 апреля 2025 года прокуратура города Краснодара сообщила о проверке доступности объектов социальной и транспортной инфраструктуры для инвалидов и других маломобильных граждан. Одним из проверенных объектов стал подземный переход через улицу Красных Партизан рядом с Краевой клинической больницей № 2. Надзорное ведомство установило отсутствие необходимых информационных знаков. Подъёмной платформой можно было воспользоваться только после прибытия сопровождающего.

Такая проблема касается не только формального наличия оборудования. Человек, использующий кресло-коляску, должен иметь реальную возможность добраться до медицинского учреждения. Отсутствие понятной информации и зависимость от неопределённого времени прибытия помощника превращают технически оснащённый переход в препятствие для самостоятельного передвижения. Применительно к больнице это может повлиять на своевременность обращения за помощью.

Ответственным организациям требуется установить, кто содержит переход и оборудование, в каком техническом состоянии находится подъёмная платформа, доступна ли информация о пользовании, предусмотрены ли необходимые меры помощи и обеспечен ли безопасный путь ко входу. Результат следует проверить на месте, а не ограничиваться формальным ответом об уже установленном оборудовании. Если обнаружены дополнительные нарушения, необходимо оформить меры их устранения в пределах компетенции ответственных лиц.

Статья 15 Федерального закона № 181-ФЗ устанавливает требования к обеспечению беспрепятственного доступа инвалидов к социальной и транспортной инфраструктуре и предоставляемым услугам. При этом обещание когда-нибудь реконструировать все городские переходы не заменяет действий по устранению выявленной проблемы. Как обеспечить доступность конкретного перехода, определить исполнителей и подтвердить выполнение законных обязанностей?',source_url='https://epp.genproc.gov.ru/ru/proc_23/mass-media/news/reg-news/?item=103018629',
 source_note='Факт: официальное сообщение органов прокуратуры https://epp.genproc.gov.ru/ru/proc_23/mass-media/news/reg-news/?item=103018629. Правовое основание: Федеральный закон от 24.11.1995 № 181-ФЗ, статья 15: доступность объектов социальной и транспортной инфраструктуры для инвалидов.',
 decision_options='["Сообщить, что платформа уже установлена, не проверяя, может ли человек реально воспользоваться ею при посещении больницы.","Предложить людям с инвалидностью самостоятельно искать другой переход, не проверяя его безопасность и доступность.","Переложить обеспечение доступа только на волонтёров, не определив обязанности собственника и обслуживающей организации.","Обеспечить фактическую доступность подъёмной платформы, организовать её безопасное использование, разместить понятные указатели и проверить пути подхода.","Ждать комплексной реконструкции всех переходов города, не устраняя нарушения доступности конкретного объекта."]'::jsonb,
 effect_plan=jsonb_set(c.effect_plan,'{options}',(SELECT jsonb_agg(
 jsonb_set(jsonb_set(o.item,'{description}',to_jsonb(
  CASE WHEN o.item->>'key'='option_4' THEN 'Проверяется фактический доступ к подъёмной платформе, наличие указателей, безопасный маршрут и организация помощи. Формальная установка подъёмника не равна обеспечению беспрепятственного доступа, когда гражданин не может воспользоваться оборудованием самостоятельно и без неопределённого ожидания.'::text ELSE ('["Сообщить, что платформа уже установлена, не проверяя, может ли человек реально воспользоваться ею при посещении больницы.","Предложить людям с инвалидностью самостоятельно искать другой переход, не проверяя его безопасность и доступность.","Переложить обеспечение доступа только на волонтёров, не определив обязанности собственника и обслуживающей организации.","Обеспечить фактическую доступность подъёмной платформы, организовать её безопасное использование, разместить понятные указатели и проверить пути подхода.","Ждать комплексной реконструкции всех переходов города, не устраняя нарушения доступности конкретного объекта."]'::jsonb->>(o.pos::integer-1)) END
 )),'{legal_basis}',to_jsonb('Федеральный закон от 24.11.1995 № 181-ФЗ, статья 15: доступность объектов социальной и транспортной инфраструктуры для инвалидов.'::text)) ORDER BY o.pos)
 FROM jsonb_array_elements(c.effect_plan->'options') WITH ORDINALITY AS o(item,pos)
 )) WHERE c.case_key='bank-curated-serious-03' AND c.effect_plan->>'best_option_key'='option_4' AND jsonb_array_length(c.decision_options)=5;
UPDATE public.event_cases AS c SET title='Владивосток: отключение электроэнергии после аварии на подстанции',situation='11 ноября 2025 года прокуратура Первомайского района Владивостока сообщила о проверке аварийного отключения электричества. По опубликованным сведениям, утром на подстанции «Улисс» произошла авария, в результате которой без электроснабжения остались свыше 20 тысяч жителей района. Отключение затронуло множество улиц, а также социально значимые объекты: детские сады № 121, 38, 43, 93 и общеобразовательные школы № 59 и 62.

Прокуратура поставила аварийно-восстановительные работы на контроль и сообщила о намерении проверить соблюдение требований при обслуживании электрических сетей, сроки устранения аварии и установление её причин. Само официальное сообщение не содержит окончательного технического заключения о причинах повреждения. Следовательно, нельзя приписывать конкретной организации неустановленные дефекты либо обещать определённый срок включения каждого объекта, если энергетики его не подтвердили.

При крупном отключении необходимо отличать технические действия сетевой организации от организационных обязанностей органов власти и подведомственных учреждений. Следует выявить объекты, где прекращение питания создаёт повышенные риски, обеспечить обмен достоверными сведениями, определить ответственных за информирование, а после восстановления проверить причины происшествия и меры предупреждения повторения. Решения по включению сетей должны учитывать безопасность персонала и граждан. Долговременное обновление инфраструктуры рассматривается отдельно от аварийного реагирования.

Статья 38 Федерального закона № 35-ФЗ закрепляет ответственность соответствующих субъектов электроэнергетики за надёжность и качество обеспечения потребителей. Какой порядок взаимодействия обеспечивает безопасное восстановление электроснабжения и контроль исполнения обязанностей, не подменяя технические заключения произвольным политическим решением?',source_url='https://epp.genproc.gov.ru/ru/proc_25/mass-media/news/regional/e6353259/',
 source_note='Факт: официальное сообщение органов прокуратуры https://epp.genproc.gov.ru/ru/proc_25/mass-media/news/regional/e6353259/. Правовое основание: Федеральный закон от 26.03.2003 № 35-ФЗ, статья 38: гарантия надёжности снабжения и ответственность субъектов электроэнергетики.',
 decision_options='["Перенести все действия на период подготовки программы модернизации электросетей, не утвердив оперативный план устранения аварии.","Сосредоточиться на публикации общих сообщений и отказаться от контроля реального восстановления электроснабжения.","Организовать безопасные аварийно-восстановительные работы, оценить последствия для социально значимых объектов, регулярно информировать жителей и проверить причины аварии.","Предложить каждому потребителю самостоятельно обеспечивать резервное электроснабжение без координации с сетевой организацией.","Устанавливать очередность подключения кварталов без данных технических специалистов и проверки безопасности линий.","Объявить длительное отключение неизбежным, не запросив результатов обследования и графика аварийных работ."]'::jsonb,
 effect_plan=jsonb_set(c.effect_plan,'{options}',(SELECT jsonb_agg(
 jsonb_set(jsonb_set(o.item,'{description}',to_jsonb(
  CASE WHEN o.item->>'key'='option_3' THEN 'Нужно организовать безопасное аварийное восстановление и получить подтверждённые сведения от сетевой организации. Последствия для социально значимых объектов требуют отдельной оценки, достоверного информирования и контроля срока устранения аварии. Техническую очередность включения линий определяют компетентные специалисты, а не произвольные решения должностных лиц.'::text ELSE ('["Перенести все действия на период подготовки программы модернизации электросетей, не утвердив оперативный план устранения аварии.","Сосредоточиться на публикации общих сообщений и отказаться от контроля реального восстановления электроснабжения.","Организовать безопасные аварийно-восстановительные работы, оценить последствия для социально значимых объектов, регулярно информировать жителей и проверить причины аварии.","Предложить каждому потребителю самостоятельно обеспечивать резервное электроснабжение без координации с сетевой организацией.","Устанавливать очередность подключения кварталов без данных технических специалистов и проверки безопасности линий.","Объявить длительное отключение неизбежным, не запросив результатов обследования и графика аварийных работ."]'::jsonb->>(o.pos::integer-1)) END
 )),'{legal_basis}',to_jsonb('Федеральный закон от 26.03.2003 № 35-ФЗ, статья 38: гарантия надёжности снабжения и ответственность субъектов электроэнергетики.'::text)) ORDER BY o.pos)
 FROM jsonb_array_elements(c.effect_plan->'options') WITH ORDINALITY AS o(item,pos)
 )) WHERE c.case_key='bank-curated-serious-06' AND c.effect_plan->>'best_option_key'='option_3' AND jsonb_array_length(c.decision_options)=6;
UPDATE public.event_cases AS c SET title='Дагестан: перебои с инсулином для ребёнка',situation='27 апреля 2026 года Генеральная прокуратура Российской Федерации опубликовала сообщение о защите прав детей на охрану здоровья. Среди приведённых случаев была жалоба жительницы Республики Дагестан, несовершеннолетний сын которой страдает сахарным диабетом. По сообщению надзорного ведомства, у семьи возникали постоянные перебои в обеспечении ребёнка лекарственными препаратами и медицинскими изделиями для контроля уровня глюкозы в крови. В ходе рассмотрения обращения региональному министру здравоохранения внесли представление, после чего мальчику выдали препараты инсулинового ряда. Обеспечение оставшимися изделиями продолжало находиться на контроле.

Этот случай показывает, что отчёт о государственных закупках сам по себе не равнозначен фактическому получению ребёнком необходимого лечения. При рассмотрении жалобы нужно сопоставить действующее назначение врача, наличие препаратов в уполномоченной аптечной сети, сведения о закупках, сроки отпуска и документы о выдаче конкретному пациенту. В случае дефицита нельзя произвольно менять назначенный инсулин или режим его применения: это вопросы профессиональной компетенции медицинских работников.

Органам здравоохранения и учреждениям необходимо определить порядок безотлагательного реагирования на подтверждённое нарушение, не перекладывая на родителей всю ответственность за поиск лекарства. При этом оперативное обеспечение конкретного пациента должно сопровождаться установлением причин задержек и мерами против повторения нарушений. Все решения о закупках, перераспределении и медицинском применении должны соответствовать действующим требованиям.

Статья 19 Федерального закона № 323-ФЗ закрепляет право на медицинскую помощь, включая гарантированный объём в рамках соответствующей программы государственных гарантий. Как восстановить лекарственное снабжение, подтвердить исполнение обязательств и обеспечить контроль так, чтобы административное решение не создавало новых медицинских рисков?',source_url='https://epp.genproc.gov.ru/ru/gprf/mass-media/news/main/e8477406/',
 source_note='Факт: официальное сообщение органов прокуратуры https://epp.genproc.gov.ru/ru/gprf/mass-media/news/main/e8477406/. Правовое основание: Федеральный закон от 21.11.2011 № 323-ФЗ, статья 19: право граждан на медицинскую помощь в гарантированном объёме.',
 decision_options='["Проверить назначение, организовать законное своевременное обеспечение инсулином под медицинским контролем, восстановить закупки и проконтролировать фактическую выдачу.","Посоветовать семье самостоятельно купить препарат, отложив выяснение причин невыполнения обязательств.","Заменить назначенный инсулин любым доступным на складе препаратом без решения лечащего врача.","Перенести решение в долгосрочный план развития аптечной сети и отказаться от срочного рассмотрения обращения.","Ограничиться письмом поставщику, не проверяя дополнительные законные возможности обеспечения ребёнка."]'::jsonb,
 effect_plan=jsonb_set(c.effect_plan,'{options}',(SELECT jsonb_agg(
 jsonb_set(jsonb_set(o.item,'{description}',to_jsonb(
  CASE WHEN o.item->>'key'='option_1' THEN 'Компетентные медицинские и снабженческие организации должны проверить назначение и индивидуальную потребность ребёнка, наличие препарата и законные способы срочного обеспечения. Выдачу требуется подтвердить, а причины срыва закупок устранить. Замена лекарства без решения врача или ожидание неопределённого срока не обеспечивают право пациента на медицинскую помощь.'::text ELSE ('["Проверить назначение, организовать законное своевременное обеспечение инсулином под медицинским контролем, восстановить закупки и проконтролировать фактическую выдачу.","Посоветовать семье самостоятельно купить препарат, отложив выяснение причин невыполнения обязательств.","Заменить назначенный инсулин любым доступным на складе препаратом без решения лечащего врача.","Перенести решение в долгосрочный план развития аптечной сети и отказаться от срочного рассмотрения обращения.","Ограничиться письмом поставщику, не проверяя дополнительные законные возможности обеспечения ребёнка."]'::jsonb->>(o.pos::integer-1)) END
 )),'{legal_basis}',to_jsonb('Федеральный закон от 21.11.2011 № 323-ФЗ, статья 19: право граждан на медицинскую помощь в гарантированном объёме.'::text)) ORDER BY o.pos)
 FROM jsonb_array_elements(c.effect_plan->'options') WITH ORDINALITY AS o(item,pos)
 )) WHERE c.case_key='bank-curated-serious-23' AND c.effect_plan->>'best_option_key'='option_1' AND jsonb_array_length(c.decision_options)=5;
DO $post$ BEGIN
IF (SELECT count(*) FROM public.event_cases c WHERE c.case_key IN ('bank-bus','bank-curated-serious-03','bank-curated-serious-06','bank-curated-serious-23') AND c.source_url LIKE 'https://%'
 AND c.effect_plan->>'best_option_key' IN ('option_1','option_3','option_4')
 AND jsonb_array_length(c.decision_options)=jsonb_array_length(c.effect_plan->'options')
 AND EXISTS(SELECT 1 FROM jsonb_array_elements(c.effect_plan->'options') op WHERE op->>'key'=c.effect_plan->>'best_option_key' AND op->>'legal_basis' LIKE 'Федеральный закон%'))<>4
THEN RAISE EXCEPTION 'Grounded event migration is incomplete'; END IF;
END $post$;